/**
 * Ryo Sakazaki crouch animation — KOF2002-quality pixel frames
 *
 * CROUCH:   4-frame crouch idle loop (breathing while low), 96x144 px
 * CROUCH_A: 3-frame crouch light punch (low jab), 96x144 px
 * CROUCH_C: 4-frame crouch heavy punch (low uppercut), 96x144 px
 * 24-color SNK palette matching ryoIdleFrames.ts / ryoAttackFrames.ts.
 *
 * Crouch anatomy (96x144 canvas):
 *   Head at y~55-75 (much lower than standing y~5-30)
 *   Body compressed: knees deeply bent, torso leaning forward
 *   Total character height ~80-90px, positioned in lower canvas
 *   Upper canvas (y=0-50) is transparent
 *
 * Palette (24 colors)
 * -------------------
 *  0  transparent
 *  1  #080604  deepest outline
 *  2  #1a1208  outline
 *  3  #2a1c10  hair deepest
 *  4  #3a2818  hair dark
 *  5  #5a3a22  hair mid
 *  6  #7a5030  hair light
 *  7  #9a6840  hair highlight
 *  8  #f5d0a0  skin light
 *  9  #e8c090  skin mid-light
 * 10  #d0a870  skin mid
 * 11  #b89058  skin dark
 * 12  #a07840  skin darker
 * 13  #886030  skin darkest
 * 14  #faf8f4  gi lightest
 * 15  #f0ece4  gi light
 * 16  #e0d8c8  gi mid-light
 * 17  #d0c4b0  gi mid
 * 18  #b8a898  gi dark
 * 19  #a09484  gi darkest
 * 20  #181410  belt / eyes black
 * 21  #ffffff  eye white / highlight
 * 22  #d83030  headband red
 * 23  #a02020  headband dark red
 */

export interface PixelFrame {
  width: number;
  height: number;
  palette: Record<number, string>;
  pixels: number[][]; // height rows x width cols, 0 = transparent
  anchor: { x: number; y: number };
}

/* ---------- shared palette ---------- */
const PALETTE: Record<number, string> = {
  0: 'transparent',
  1: '#080604',
  2: '#1a1208',
  3: '#2a1c10',
  4: '#3a2818',
  5: '#5a3a22',
  6: '#7a5030',
  7: '#9a6840',
  8: '#f5d0a0',
  9: '#e8c090',
  10: '#d0a870',
  11: '#b89058',
  12: '#a07840',
  13: '#886030',
  14: '#faf8f4',
  15: '#f0ece4',
  16: '#e0d8c8',
  17: '#d0c4b0',
  18: '#b8a898',
  19: '#a09484',
  20: '#181410',
  21: '#ffffff',
  22: '#d83030',
  23: '#a02020',
};

// ─────────────────────────────────────────────────────────────
// Encoding: each char maps to a palette index
// '.' = 0 (transparent)
// '0'-'9' = indices 0-9
// 'a'-'n' = indices 10-23
// ─────────────────────────────────────────────────────────────

const W = 96;
function r(s: string): number[] {
  const padded = s.padEnd(W, '.').slice(0, W);
  return padded.split('').map(ch => {
    if (ch === '.') return 0;
    if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
    if (ch >= 'a' && ch <= 'n') return ch.charCodeAt(0) - 87;
    return 0;
  });
}

