//   1=#080604  2=#1a1208  3=#2a1c10  4=#3a2818  5=#5a3a22
//   6=#7a5030  7=#9a6840  8=#f5d0a0  9=#e8c090  a=#d0a870
//   b=#b89058  c=#a07840  d=#886030  e=#faf8f4  f=#f0ece4
//   g=#e0d8c8  h=#d0c4b0  i=#b8a898  j=#a09484  k=#181410
//   l=#ffffff  m=#d83030  n=#a02020

